## Every exported ilm_*() answers to iml_*() as well, as in illume and illumex:
## the transposition is an easy one to type. The aliases are generated by
## dev/make_iml_aliases.R, and this is what notices when a new export has been
## added without one.

limn_exports <- function() {
  ns <- readLines(system.file("NAMESPACE", package = "limn"))
  sub("^export\\((.*)\\)$", "\\1", grep("^export\\(", ns, value = TRUE))
}

test_that("every exported ilm_*() has an exported iml_*() alias", {
  ex <- limn_exports()
  ilm <- grep("^ilm_", ex, value = TRUE)
  want <- sub("^ilm_", "iml_", ilm)
  missing <- setdiff(want, ex)
  expect(length(missing) == 0L,
         paste0("no iml_*() alias for: ", paste(missing, collapse = ", "),
                ". Run dev/make_iml_aliases.R, then devtools::document()."))
  ## and no alias outlives the function it named
  stale <- setdiff(grep("^iml_", ex, value = TRUE), want)
  expect(length(stale) == 0L,
         paste0("iml_*() aliases with no ilm_*() behind them: ",
                paste(stale, collapse = ", "),
                ". Run dev/make_iml_aliases.R, then devtools::document()."))
})

test_that("an alias IS the function it names, not a wrapper around it", {
  ns <- asNamespace("limn")
  ilm <- grep("^ilm_", limn_exports(), value = TRUE)
  same <- vapply(ilm, function(f)
    identical(get(f, envir = ns), get(sub("^ilm_", "iml_", f), envir = ns)),
    TRUE)
  expect_true(all(same), label = paste("identical:",
                                       paste(ilm[!same], collapse = ", ")))
})

test_that("no limn export shadows an illume or illumex export", {
  ## limn attaches after illume and illumex, so a shared name would mask theirs.
  ## A shared verb belongs in illume as an S3 generic, with limn's method on it.
  theirs <- c(getNamespaceExports("illume"), getNamespaceExports("illumex"))
  clash <- intersect(limn_exports(), theirs)
  expect(length(clash) == 0L,
         paste0("limn exports names that illume or illumex already export: ",
                paste(clash, collapse = ", "),
                ". Make the verb an S3 generic in illume, and give limn a method."))
})
